<?php
require_once dirname(__DIR__,2).'/app/helpers.php';require_role('admin');require_once dirname(__DIR__,2).'/app/Services/AdminOperationsService.php';$svc=new AdminOperationsService(Database::connection());$q=trim($_GET['q']??'');$status=trim($_GET['status']??'');$rows=$svc->transactionSearch($q,$status);$statuses=['processing','completed','failed','reversed','refunded'];
?><!doctype html><html lang="<?=e(current_locale())?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e(t('Transactions'))?> - <?=e(t('Admin'))?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container-fluid p-4"><div class="d-flex justify-content-between mb-4"><h2><?=e(t('Transaction Operations'))?></h2><a href="<?=url('admin/')?>"><?=e(t('Admin dashboard'))?></a></div><form class="row g-2 mb-4"><div class="col-md-5"><input name="q" value="<?=e($q)?>" class="form-control" placeholder="<?=e(t('Reference, email, account or description'))?>"></div><div class="col-md-3"><select name="status" class="form-select"><option value=""><?=e(t('All statuses'))?></option><?php foreach($statuses as $s):?><option <?=$status===$s?'selected':''?>><?=e(tx_label($s))?></option><?php endforeach;?></select></div><div class="col-auto"><button class="btn btn-primary"><?=e(t('Search'))?></button></div></form><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th><?=e(t('Reference'))?></th><th><?=e(t('Type'))?></th><th><?=e(t('Amount'))?></th><th><?=e(t('Status'))?></th><th><?=e(t('Customer'))?></th><th><?=e(t('Account'))?></th><th><?=e(t('Created'))?></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['reference'])?></td><td><?=e(tx_label($r['type']))?></td><td>$<?=number_format((float)$r['amount'],2)?></td><td><span class="badge text-bg-secondary"><?=e(tx_label($r['status']))?></span></td><td><?=e($r['email']??'—')?></td><td><?=e($r['account_number']??'—')?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></body></html>
